// n8n Code node, mode: Run Once for All Items.
// Based on parts/n8n-max/code/max-webhook-guard.js.txt: secret check and normalisation are the same,
// the callback branch passes the raw payload (the booking dialog has its own payload scheme).
const envelope = $input.first().json || {};
const body = envelope.body && typeof envelope.body === 'object' && !Array.isArray(envelope.body)
  ? envelope.body : envelope;
const headers = envelope.headers && typeof envelope.headers === 'object' ? envelope.headers : {};

const ignored = (errorCode, statusCode = 204) => [{ json: {
  accepted: false, status_code: statusCode, error_code: errorCode
} }];
const header = (name) => {
  const wanted = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === wanted) return String(value || '');
  }
  return '';
};
const sameSecret = (left, right) => {
  const a = String(left || '');
  const b = String(right || '');
  const length = Math.max(a.length, b.length, 1);
  let difference = a.length ^ b.length;
  for (let index = 0; index < length; index += 1) {
    difference |= (a.charCodeAt(index) || 0) ^ (b.charCodeAt(index) || 0);
  }
  return difference === 0;
};
const normalizeTs = (value) => {
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed) || parsed <= 0) return 0;
  return parsed < 100000000000 ? parsed * 1000 : parsed;
};

const expectedSecret = String($env.{{CLIENT_CODE_UPPER}}_MAX_WEBHOOK_SECRET || '');
if (!/^[A-Za-z0-9_-]{5,256}$/.test(expectedSecret)) return ignored('max_secret_not_configured', 503);
if (!sameSecret(expectedSecret, header('x-max-bot-api-secret'))) return ignored('max_secret_mismatch', 401);
if (!body || !['message_created', 'message_callback', 'bot_started'].includes(body.update_type)) {
  return ignored('max_event_ignored');
}
// dry run is honoured only after the secret was verified: actions are returned, nothing is sent
const dry = header('x-dry-run') === '1';

const accept = (fields) => {
  const f = Object.assign({ kind: '', event_id: '', user_id: '', text: '', payload: '', callback_id: '', mid: '' }, fields);
  f.user_id = String(f.user_id ?? '').trim();
  f.event_id = String(f.event_id ?? '').trim();
  f.text = String(f.text ?? '').normalize('NFKC').trim().slice(0, 500);
  f.payload = String(f.payload ?? '').slice(0, 300);
  f.callback_id = String(f.callback_id ?? '').trim();
  f.mid = String(f.mid ?? '').trim();
  if (!/^[0-9]{1,19}$/.test(f.user_id) || !f.event_id || f.event_id.length > 200) return ignored('max_event_invalid', 400);
  return [{ json: Object.assign({ accepted: true, status_code: 200, dry }, f) }];
};

if (body.update_type === 'bot_started') {
  const userId = body.user && body.user.user_id;
  return accept({ kind: 'start', user_id: userId, event_id: `bot-started:${body.chat_id}:${normalizeTs(body.timestamp)}` });
}

if (body.update_type === 'message_callback') {
  const callback = body.callback && typeof body.callback === 'object' ? body.callback : {};
  const message = body.message && typeof body.message === 'object' ? body.message : {};
  const mbody = message.body && typeof message.body === 'object' ? message.body : {};
  return accept({ kind: 'callback', user_id: callback.user && callback.user.user_id, event_id: callback.callback_id,
    callback_id: callback.callback_id, payload: callback.payload, mid: mbody.mid });
}

const message = body.message && typeof body.message === 'object' ? body.message : {};
const messageBody = message.body && typeof message.body === 'object' ? message.body : {};
const sender = message.sender && typeof message.sender === 'object' ? message.sender : {};
if (sender.is_bot === true) return ignored('max_bot_event_ignored');
const text = typeof messageBody.text === 'string' ? messageBody.text.normalize('NFKC').trim() : '';
if (!text) return ignored('max_nontext_event_ignored');
return accept({ kind: 'message', user_id: sender.user_id ?? (body.user && body.user.user_id),
  event_id: messageBody.mid ?? messageBody.message_id ?? message.message_id ?? message.mid, text, mid: messageBody.mid });

// n8n Code node, mode: Run Once for All Items.
// Event + dialog context -> handler, one whitelisted SQL (constants only, values go as parameters).
const SC = '{{CLIENT_CODE}}_booking';
const ev = $('Guard').first().json;
const ctx = ($input.first().json || {}).ctx || {};
const isAdmin = ctx.admin === true;
const step = String(ctx.step || '');
const data = ctx.data && typeof ctx.data === 'object' ? ctx.data : {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const DAY = /^\d{4}-\d{2}-\d{2}$/;
const NOP = "select '{}'::jsonb as r";
const Q = {
  svcs: `select coalesce(jsonb_agg(jsonb_build_object('id',service_id,'title',title,'min',duration_minutes,'price',price_minor)),'[]'::jsonb) as r from ${SC}.list_services()`,
  staff: `select coalesce(jsonb_agg(jsonb_build_object('id',staff_id,'name',display_name)),'[]'::jsonb) as r from ${SC}.list_staff($1::uuid)`,
  days: `select coalesce(jsonb_agg(d order by d),'[]'::jsonb) as r from (select distinct to_char((starts_at at time zone 'Europe/Moscow')::date,'YYYY-MM-DD') as d from ${SC}.free_slots($1::uuid, nullif($2,'any')::uuid, current_date, current_date+27)) x`,
  slots: `select coalesce(jsonb_agg(jsonb_build_object('id',slot_id,'t',to_char(starts_at at time zone 'Europe/Moscow','HH24:MI'),'staff',staff_name) order by starts_at),'[]'::jsonb) as r from ${SC}.free_slots($1::uuid, nullif($2,'any')::uuid, $3::date, $3::date)`,
  summary: `select ${SC}.bot_slot_summary($1::uuid,$2::uuid) as r`,
  create: `select ${SC}.bot_create_appointment($1::bigint,$2::uuid,$3::uuid,$4::uuid,$5::uuid,$6,$7) as r`,
  acreate: `select ${SC}.bot_admin_create_appointment($1::bigint,$2::uuid,$3::uuid,$4::uuid,$5,$6) as r`,
  my: `select ${SC}.bot_my_appointments($1::bigint) as r`,
  cancel: `select ${SC}.bot_cancel_appointment($1::bigint,$2::uuid) as r`,
  consent: `with c as (select ${SC}.bot_grant_consent($1::bigint)) select '{}'::jsonb as r from c`,
  alist: `select coalesce(jsonb_agg(jsonb_build_object('id',appointment_uuid,'t',to_char(starts_at at time zone 'Europe/Moscow','HH24:MI'),'svc',service_title,'staff',staff_name,'name',customer_name,'phone',customer_phone,'src',source) order by starts_at),'[]'::jsonb) as r from ${SC}.admin_list_appointments($1::bigint,$2::date,false)`,
  acancel: `select to_jsonb(${SC}.admin_cancel_appointment($1::bigint,$2::uuid,'cancelled by administrator')) as r`,
  astaff: `select coalesce(jsonb_agg(jsonb_build_object('id',staff_id,'name',display_name,'active',is_active)),'[]'::jsonb) as r from ${SC}.admin_list_staff($1::bigint)`,
  aexc: `select to_jsonb(e) as r from ${SC}.admin_set_exception($1::bigint,$2::uuid,$3::date,false,null,null,'bot') e`,
  arem: `select to_jsonb(${SC}.admin_remove_exception($1::bigint,$2::uuid,$3::date)) as r`,
  awh: `select to_jsonb(w) as r from ${SC}.admin_set_work_hours($1::bigint,$2::uuid,$3::int,$4::time,$5::time) w`,
  asvc: `select coalesce(jsonb_agg(jsonb_build_object('id',service_id,'title',title,'min',duration_minutes,'price',price_minor,'active',is_active)),'[]'::jsonb) as r from ${SC}.admin_list_services($1::bigint)`,
  aupd: `select to_jsonb(${SC}.admin_update_service($1::bigint,$2::uuid,$3,$4::int,$5::bigint,false)) as r`,
  aact: `select to_jsonb(${SC}.admin_set_service_active($1::bigint,$2::uuid,$3::boolean)) as r`,
  aadd: `select to_jsonb(${SC}.admin_add_service($1::bigint,$2,$3::int,$4::bigint,null)) as r`
};
const uuidFrom = (s) => {
  const h = require('crypto').createHash('sha256').update(s).digest('hex');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-8${h.slice(17, 20)}-${h.slice(20, 32)}`;
};
const uid = ev.user_id;
const go = (handler, sql, params, extra) => [{ json: Object.assign({
  ev, ctx, handler, sql: sql ? Q[sql] : NOP, params: params || []
}, extra || {}) }];
const menu = () => go(isAdmin ? 'amenu' : 'menu');
const bad = (v, re) => !re.test(String(v || ''));

if (ctx.fresh === false) return go('dup');
if (ev.kind === 'start') return menu();

// ---------- text input ----------
if (ev.kind === 'message') {
  const t = ev.text;
  if (step === 'name' && data.svc && data.slot) {
    if (t.length < 2 || t.length > 80) return go('ask_name_again', null, [], { st: data });
    return go('ask_phone', null, [], { st: Object.assign({}, data, { name: t }) });
  }
  if (step === 'phone' && data.svc && data.slot && data.name) {
    const digits = t.replace(/\D/g, '');
    if (digits.length < 10 || digits.length > 15) return go('ask_phone_again', null, [], { st: data });
    const st = Object.assign({}, data, { phone: t.slice(0, 40) });
    if (data.mode === 'p') {
      if (!isAdmin) return menu();
      const appt = uuidFrom(`a|${uid}|${data.slot}|${data.n}`);
      return go('acreate', 'acreate', [uid, appt, data.svc, data.slot, data.name, st.phone], { st });
    }
    return go('summary', 'summary', [data.svc, data.slot], { st });
  }
  if (isAdmin && step === 'ahours' && data.sid && data.dow !== undefined) {
    const m = t.match(/^(\d{1,2})[:.](\d{2})\s*[-–—]\s*(\d{1,2})[:.](\d{2})$/);
    if (!m) return go('ahours_again', null, [], { st: data });
    const a = `${m[1].padStart(2, '0')}:${m[2]}`;
    const b = `${m[3].padStart(2, '0')}:${m[4]}`;
    return go('ahours', 'awh', [uid, data.sid, String(data.dow), a, b], { st: data });
  }
  if (isAdmin && (step === 'aedit' || step === 'anew')) {
    const parts = t.split(';').map((s) => s.trim());
    const dur = Number(parts[1]);
    const price = Number(String(parts[2] || '').replace(',', '.').replace(/\s/g, ''));
    if (parts.length !== 3 || parts[0].length < 2 || !Number.isInteger(dur) || dur < 5 || dur > 600
      || !Number.isFinite(price) || price < 0) return go('aedit_again', null, [], { st: data, step });
    const minor = String(Math.round(price * 100));
    if (step === 'aedit' && data.id) return go('aupd', 'aupd', [uid, data.id, parts[0], String(dur), minor]);
    if (step === 'anew') return go('aadd', 'aadd', [uid, parts[0], String(dur), minor]);
  }
  return menu();
}

// ---------- button presses ----------
const [cmd, ...a] = String(ev.payload || '').split(':');
const mode = ['psvc', 'pstf', 'pdays', 'pday', 'pslot'].includes(cmd) ? 'p' : '';
const c = mode ? cmd.slice(1) : cmd;
if (mode && !isAdmin) return menu();
const adminOnly = ['adays', 'ad', 'ac', 'abook', 'ast', 'as', 'ax', 'axd', 'ar', 'ard', 'aw', 'awd', 'asv', 'asi', 'ase', 'asa', 'asn', 'amenu'];
if (adminOnly.includes(cmd) && !isAdmin) return menu();

switch (c) {
  case 'menu': return menu();
  case 'book':
    if (!ctx.consent) return go('consent_ask');
    return go('svcs', 'svcs', [], { mode: '' });
  case 'abook': return go('svcs', 'svcs', [], { mode: 'p' });
  case 'consent': return go('consent_yes', 'consent', [uid]);
  case 'svc':
    if (bad(a[0], UUID)) return menu();
    return go('staff', 'staff', [a[0]], { mode, svc: a[0] });
  case 'stf':
  case 'days': {
    if (bad(a[0], UUID) || (a[1] !== 'any' && bad(a[1], UUID))) return menu();
    return go('days', 'days', [a[0], a[1]], { mode, svc: a[0], stf: a[1], off: c === 'days' ? Math.max(0, parseInt(a[2], 10) || 0) : 0 });
  }
  case 'day':
    if (bad(a[0], UUID) || (a[1] !== 'any' && bad(a[1], UUID)) || bad(a[2], DAY)) return menu();
    return go('slots', 'slots', [a[0], a[1], a[2]], { mode, svc: a[0], stf: a[1], day: a[2] });
  case 'slot':
    if (bad(a[0], UUID) || bad(a[1], UUID)) return menu();
    return go('ask_name', null, [], { mode, st: { svc: a[0], slot: a[1], mode, n: ev.event_id.slice(0, 40) } });
  case 'ok': {
    if (step !== 'confirm' || !data.svc || !data.slot || !data.name || !data.phone) return menu();
    const appt = uuidFrom(`b|${uid}|${data.slot}|${data.n}`);
    const cons = uuidFrom(`c|${uid}|${data.n}`);
    return go('created', 'create', [uid, appt, cons, data.svc, data.slot, data.name, data.phone]);
  }
  case 'my': return go('my', 'my', [uid]);
  case 'cancel':
    if (bad(a[0], UUID)) return menu();
    return go('cancelled', 'cancel', [uid, a[0]]);
  case 'rem_ok': return go('rem_ok');
}
switch (cmd) {
  case 'amenu': return menu();
  case 'adays': return go('adays');
  case 'ad':
    if (bad(a[0], DAY)) return menu();
    return go('alist', 'alist', [uid, a[0]], { day: a[0] });
  case 'ac':
    if (bad(a[0], UUID)) return menu();
    return go('acancelled', 'acancel', [uid, a[0]]);
  case 'ast': return go('ast', 'astaff', [uid]);
  case 'as':
    if (bad(a[0], UUID)) return menu();
    return go('as', 'astaff', [uid], { sid: a[0] });
  case 'ax': case 'ar':
    if (bad(a[0], UUID)) return menu();
    return go('pickdate', null, [], { sid: a[0], what: cmd });
  case 'axd':
    if (bad(a[0], UUID) || bad(a[1], DAY)) return menu();
    return go('aexc', 'aexc', [uid, a[0], a[1]], { sid: a[0], day: a[1] });
  case 'ard':
    if (bad(a[0], UUID) || bad(a[1], DAY)) return menu();
    return go('arem', 'arem', [uid, a[0], a[1]], { sid: a[0], day: a[1] });
  case 'aw':
    if (bad(a[0], UUID)) return menu();
    return go('pickdow', null, [], { sid: a[0] });
  case 'awd': {
    const dow = parseInt(a[1], 10);
    if (bad(a[0], UUID) || !(dow >= 0 && dow <= 6)) return menu();
    return go('ask_hours', null, [], { st: { sid: a[0], dow } });
  }
  case 'asv': return go('asv', 'asvc', [uid]);
  case 'asi':
    if (bad(a[0], UUID)) return menu();
    return go('asi', 'asvc', [uid], { sid: a[0] });
  case 'ase':
    if (bad(a[0], UUID)) return menu();
    return go('ask_edit', null, [], { st: { id: a[0] } });
  case 'asn': return go('ask_new', null, []);
  case 'asa':
    if (bad(a[0], UUID) || !['0', '1'].includes(a[1])) return menu();
    return go('aact', 'aact', [uid, a[0], a[1] === '1' ? 'true' : 'false'], { sid: a[0], on: a[1] === '1' });
}
return menu();

// n8n Code node, mode: Run Once for All Items.
// Route result + SQL result -> actions for MAX, next dialog state, notifications to administrators.
const rt = $('Route').first().json;
const ev = rt.ev;
const ctx = rt.ctx || {};
const exec = $input.first().json || {};
const failed = !!exec.error;
const r = exec.r;
const mode = rt.mode || '';
const isAdmin = ctx.admin === true;
const admins = (Array.isArray(ctx.admins) ? ctx.admins : []).map(String);
const API = 'https://platform-api2.max.ru';
// How a pressed button changes the screen. Stand check 09.10.2026: see 00_ШАПКА.md.
const SCREEN_MODE = '{{SCREEN_MODE}}'; // answer = POST /answers with message, edit = PUT /messages

const WD = ['Вс', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'];
const pad = (n) => String(n).padStart(2, '0');
const msk = (iso) => new Date(new Date(iso).getTime() + 3 * 3600 * 1000);
const fmtDT = (iso) => { const d = msk(iso); return `${pad(d.getUTCDate())}.${pad(d.getUTCMonth() + 1)} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`; };
const fmtDay = (ymd) => { const d = new Date(`${ymd}T00:00:00Z`); return `${ymd.slice(8, 10)}.${ymd.slice(5, 7)} ${WD[d.getUTCDay()]}`; };
const rub = (minor) => (minor == null ? '' : `${Math.round(Number(minor) / 100)} ₽`);
const todayMsk = () => msk(new Date().toISOString()).toISOString().slice(0, 10);
const addDays = (ymd, n) => new Date(new Date(`${ymd}T00:00:00Z`).getTime() + n * 86400000).toISOString().slice(0, 10);
const btn = (text, payload) => ({ type: 'callback', text: String(text).slice(0, 60), payload });
const rows = (arr, per) => { const o = []; for (let i = 0; i < arr.length; i += per) o.push(arr.slice(i, i + per)); return o; };
const MENU_BTN = [btn('Меню', 'menu')];

let text = '';
let kb = [];
let state = 'keep'; // keep | clear | {step, data}
const notes = []; // [{user_id, text}]
let notification = '';

const A_BACK = [btn('Назад', 'amenu')];
const book = mode === 'p' ? 'abook' : 'book';
const P = (c) => `${mode}${c}`;
const menuScreen = () => {
  text = 'Здравствуйте! Здесь можно записаться на услугу и посмотреть свои записи.';
  kb = [[btn('Записаться', 'book')], [btn('Мои записи', 'my')]];
  state = 'clear';
};
const amenuScreen = () => {
  text = 'Меню администратора';
  kb = [[btn('Записи на день', 'adays')], [btn('Запись по телефону', 'abook')], [btn('Графики', 'ast')], [btn('Услуги', 'asv')]];
  state = 'clear';
};
const stale = (msg, back) => { text = msg; kb = [back || MENU_BTN]; };
const cardLines = (c) => `Услуга: ${c.service_title}\nМастер: ${c.staff_name}\nКогда: ${fmtDT(c.starts_at)}${c.price_minor != null ? `\nЦена: ${rub(c.price_minor)}` : ''}`;
const slotRows = (slots, svc, pre) => {
  const showStaff = new Set(slots.map((s) => s.staff)).size > 1;
  return rows(slots.map((s) => btn(showStaff ? `${s.t} ${s.staff}` : s.t, `${pre}slot:${svc}:${s.id}`)), showStaff ? 2 : 3);
};

if (failed) {
  text = 'Что-то пошло не так, попробуйте еще раз чуть позже.';
  kb = [isAdmin ? A_BACK : MENU_BTN];
} else switch (rt.handler) {
  case 'dup': break;
  case 'menu': menuScreen(); break;
  case 'amenu': amenuScreen(); break;
  case 'consent_ask':
    text = 'Для записи нужно согласие на обработку персональных данных.\n\nЯ даю согласие на обработку персональных данных для записи на услугу, подтверждения и напоминания о визите и ознакомлен(а) с Политикой обработки персональных данных.';
    kb = [[btn('Согласен', 'consent:yes')], MENU_BTN];
    break;
  case 'consent_yes':
  case 'svcs': {
    // consent_yes arrives here with an empty result: show services through the same screen on the next press
    if (rt.handler === 'consent_yes') {
      text = 'Спасибо! Согласие записано. Теперь можно записаться.';
      kb = [[btn('Записаться', 'book')], MENU_BTN];
      break;
    }
    const list = Array.isArray(r) ? r : [];
    if (!list.length) { stale('Сейчас нет доступных услуг.', mode === 'p' ? A_BACK : MENU_BTN); break; }
    text = mode === 'p' ? 'Запись по телефону. Выберите услугу:' : 'Выберите услугу:';
    kb = list.map((s) => [btn(`${s.title} · ${s.min} мин${s.price != null ? ` · ${rub(s.price)}` : ''}`, `${P('svc')}:${s.id}`)]);
    kb.push(mode === 'p' ? A_BACK : MENU_BTN);
    state = 'clear';
    break;
  }
  case 'staff': {
    const list = Array.isArray(r) ? r : [];
    if (!list.length) { stale('Эта услуга сейчас недоступна. Выберите другую.', [btn('К услугам', book)]); break; }
    text = 'Выберите мастера:';
    kb = list.map((s) => [btn(s.name, `${P('stf')}:${rt.svc}:${s.id}`)]);
    kb.push([btn('Любой мастер', `${P('stf')}:${rt.svc}:any`)]);
    kb.push([btn('Назад', book)]);
    break;
  }
  case 'days': {
    const days = Array.isArray(r) ? r : [];
    if (!days.length) { stale('Свободного времени пока нет. Выберите другого мастера или услугу.', [btn('Назад', `${P('svc')}:${rt.svc}`)]); break; }
    const page = days.slice(rt.off, rt.off + 7);
    if (!page.length) { stale('Дальше дней нет.', [btn('Назад', `${P('stf')}:${rt.svc}:${rt.stf}`)]); break; }
    text = 'Выберите день:';
    kb = rows(page.map((d) => btn(fmtDay(d), `${P('day')}:${rt.svc}:${rt.stf}:${d}`)), 2);
    if (rt.off + 7 < days.length) kb.push([btn('Дальше →', `${P('days')}:${rt.svc}:${rt.stf}:${rt.off + 7}`)]);
    kb.push([btn('Назад', `${P('svc')}:${rt.svc}`)]);
    break;
  }
  case 'slots': {
    const slots = Array.isArray(r) ? r : [];
    if (!slots.length) { stale('На этот день время уже занято. Выберите другой день.', [btn('Другой день', `${P('stf')}:${rt.svc}:${rt.stf}`)]); break; }
    text = `Свободное время, ${fmtDay(rt.day)}:`;
    kb = slotRows(slots, rt.svc, mode);
    kb.push([btn('Назад', `${P('stf')}:${rt.svc}:${rt.stf}`)]);
    break;
  }
  case 'ask_name':
    text = mode === 'p' ? 'Как зовут клиента? Напишите имя сообщением.' : 'Как вас зовут? Напишите имя сообщением.';
    kb = [[btn('Отмена', 'menu')]];
    state = { step: 'name', data: rt.st };
    break;
  case 'ask_name_again':
    text = 'Имя должно быть от 2 до 80 знаков. Напишите имя еще раз.';
    kb = [[btn('Отмена', 'menu')]];
    break;
  case 'ask_phone':
    text = 'Напишите номер телефона, например +7 900 123-45-67.';
    kb = [[btn('Отмена', 'menu')]];
    state = { step: 'phone', data: rt.st };
    break;
  case 'ask_phone_again':
    text = 'Не похоже на номер телефона. Напишите его еще раз, например +7 900 123-45-67.';
    kb = [[btn('Отмена', 'menu')]];
    break;
  case 'summary': {
    if (!r || !r.service_title) { stale('Это время уже недоступно. Начните запись заново.', [btn('Записаться', 'book')]); state = 'clear'; break; }
    text = `Проверьте запись:\n${cardLines(r)}\nИмя: ${rt.st.name}\nТелефон: ${rt.st.phone}`;
    kb = [[btn('Подтвердить', 'ok')], [btn('Изменить', 'book')]];
    state = { step: 'confirm', data: rt.st };
    break;
  }
  case 'created':
  case 'acreate': {
    const res = r && r.result;
    const st = rt.st || ctx.data || {};
    if (res === 'ok') {
      const c = r.card;
      if (rt.handler === 'created') {
        text = `Вы записаны.\n${cardLines(c)}\nНапомню о визите за сутки и за 2 часа.`;
        kb = [[btn('Мои записи', 'my')], MENU_BTN];
      } else {
        text = `Запись создана.\n${cardLines(c)}\nКлиент: ${c.customer_name}, ${c.customer_phone}`;
        kb = [A_BACK];
      }
      state = 'clear';
      const who = rt.handler === 'created' ? 'через бота' : 'по телефону';
      for (const id of admins) if (id !== ev.user_id) {
        notes.push({ user_id: id, text: `Новая запись (${who}).\n${cardLines(c)}\nКлиент: ${c.customer_name}, ${c.customer_phone}` });
      }
    } else if (res === 'taken') {
      const slots = (r.slots || []).map((s) => ({ id: s.slot_id, t: fmtDT(s.starts_at).slice(6), staff: s.staff_name }));
      const pre = rt.handler === 'acreate' ? 'p' : '';
      if (slots.length) {
        text = 'Это время только что заняли. Выберите другое:';
        kb = slotRows(slots, ctx.data && ctx.data.svc ? ctx.data.svc : st.svc, pre);
      } else { text = 'Это время только что заняли, на этот день свободного времени больше нет.'; kb = []; }
      kb.push([btn('К началу', pre ? 'abook' : 'book')]);
      state = 'clear';
    } else if (res === 'no_consent') {
      text = 'Для записи нужно согласие на обработку персональных данных. Нажмите «Записаться» и подтвердите его.';
      kb = [[btn('Записаться', 'book')]];
      state = 'clear';
    } else if (res === 'bad_phone') {
      text = 'Телефон не принят. Напишите номер еще раз, например +7 900 123-45-67.';
      kb = [[btn('Отмена', 'menu')]];
      state = { step: 'phone', data: Object.assign({}, st, { phone: undefined }) };
    } else if (res === 'forbidden') {
      menuScreen();
    } else {
      text = 'Не получилось оформить запись. Попробуйте позже или позвоните в салон.';
      kb = [isAdmin ? A_BACK : MENU_BTN];
      state = 'clear';
    }
    break;
  }
  case 'my': {
    const list = (Array.isArray(r) ? r : []).filter((c) => ['planned', 'confirmed'].includes(c.status));
    if (!list.length) { text = 'Предстоящих записей нет.'; kb = [[btn('Записаться', 'book')], MENU_BTN]; state = 'clear'; break; }
    text = 'Ваши записи:\n' + list.map((c) => `• ${fmtDT(c.starts_at)} — ${c.service_title}, ${c.staff_name}${c.can_cancel ? '' : ' (онлайн отменить нельзя, позвоните в салон)'}`).join('\n');
    kb = list.filter((c) => c.can_cancel).map((c) => [btn(`Отменить ${fmtDT(c.starts_at)}`, `cancel:${c.appointment_uuid}`)]);
    kb.push(MENU_BTN);
    state = 'clear';
    break;
  }
  case 'cancelled': {
    const res = r && r.result;
    if (res === 'ok') {
      text = `Запись отменена.\n${cardLines(r.card)}`;
      kb = [[btn('Записаться', 'book')], MENU_BTN];
      for (const id of admins) if (id !== ev.user_id) {
        notes.push({ user_id: id, text: `Отмена записи клиентом.\n${cardLines(r.card)}\nКлиент: ${r.card.customer_name}, ${r.card.customer_phone}` });
      }
    } else if (res === 'too_late') {
      text = `Отменить онлайн уже нельзя: до визита меньше ${r.cancel_hours} ч. Позвоните в салон.`;
      kb = [MENU_BTN];
    } else {
      text = 'Эта запись уже отменена или не найдена.';
      kb = [MENU_BTN];
    }
    break;
  }
  case 'rem_ok':
    text = 'Спасибо, ждем вас!';
    kb = [MENU_BTN];
    notification = 'Ждем вас';
    break;
  // ----- administrator -----
  case 'adays': {
    const t0 = todayMsk();
    text = 'Записи на какой день?';
    kb = rows(Array.from({ length: 7 }, (_, i) => btn(fmtDay(addDays(t0, i)), `ad:${addDays(t0, i)}`)), 2);
    kb.push(A_BACK);
    break;
  }
  case 'alist': {
    const list = Array.isArray(r) ? r : [];
    text = `Записи, ${fmtDay(rt.day)}:` + (list.length ? '\n' + list.map((x) => `${x.t} ${x.svc}, ${x.staff} — ${x.name}, ${x.phone}${x.src === 'bot' ? '' : ` (${x.src})`}`).join('\n') : '\nнет записей');
    kb = list.map((x) => [btn(`Отменить ${x.t} ${x.name}`, `ac:${x.id}`)]);
    kb.push([btn('Назад', 'adays')]);
    break;
  }
  case 'acancelled':
    text = r === true ? 'Запись отменена, время освобождено.' : 'Не удалось отменить: запись не найдена или уже отменена.';
    kb = [[btn('К дням', 'adays')], A_BACK];
    break;
  case 'ast': {
    const list = Array.isArray(r) ? r : [];
    text = 'Графики. Выберите мастера:';
    kb = list.map((s) => [btn(`${s.name}${s.active ? '' : ' (скрыт)'}`, `as:${s.id}`)]);
    kb.push(A_BACK);
    break;
  }
  case 'as': {
    const s = (Array.isArray(r) ? r : []).find((x) => x.id === rt.sid);
    if (!s) { stale('Мастер не найден.', [btn('Назад', 'ast')]); break; }
    text = `Мастер: ${s.name}. Что сделать?`;
    kb = [[btn('Выходной на дату', `ax:${s.id}`)], [btn('Часы дня недели', `aw:${s.id}`)], [btn('Снять исключение', `ar:${s.id}`)], [btn('Назад', 'ast')]];
    break;
  }
  case 'pickdate': {
    const t0 = todayMsk();
    const code = rt.what === 'ax' ? 'axd' : 'ard';
    text = rt.what === 'ax' ? 'Какая дата будет выходной?' : 'С какой даты снять исключение?';
    kb = rows(Array.from({ length: 14 }, (_, i) => btn(fmtDay(addDays(t0, i)), `${code}:${rt.sid}:${addDays(t0, i)}`)), 3);
    kb.push([btn('Назад', `as:${rt.sid}`)]);
    break;
  }
  case 'aexc':
    text = `Выходной на ${fmtDay(rt.day)} установлен. Убрано окон: ${r.removed_slots}.` + (r.active_appointments > 0 ? `\nВнимание: на этот день есть записи (${r.active_appointments}), их нужно отменить или перенести вручную.` : '');
    kb = [[btn('Назад', `as:${rt.sid}`)]];
    break;
  case 'arem':
    text = r === true ? `Исключение на ${fmtDay(rt.day)} снято, окна вернулись по графику.` : 'На эту дату исключения не было.';
    kb = [[btn('Назад', `as:${rt.sid}`)]];
    break;
  case 'pickdow':
    text = 'Для какого дня недели изменить часы?';
    kb = rows([1, 2, 3, 4, 5, 6, 0].map((d) => btn(WD[d], `awd:${rt.sid}:${d}`)), 4);
    kb.push([btn('Назад', `as:${rt.sid}`)]);
    break;
  case 'ask_hours':
    text = 'Напишите часы работы одной строкой, например 10:00-18:00.';
    kb = [[btn('Отмена', 'amenu')]];
    state = { step: 'ahours', data: rt.st };
    break;
  case 'ahours_again':
    text = 'Не понял. Формат: 10:00-18:00.';
    kb = [[btn('Отмена', 'amenu')]];
    break;
  case 'ahours':
    text = `Часы сохранены. Убрано окон: ${r.removed_slots}, добавлено: ${r.created_slots}.`;
    kb = [[btn('Назад', `as:${rt.st.sid}`)]];
    state = 'clear';
    break;
  case 'asv': {
    const list = Array.isArray(r) ? r : [];
    text = 'Услуги:';
    kb = list.map((s) => [btn(`${s.title} · ${s.min} мин · ${rub(s.price)}${s.active ? '' : ' (скрыта)'}`, `asi:${s.id}`)]);
    kb.push([btn('Добавить услугу', 'asn')], A_BACK);
    break;
  }
  case 'asi': {
    const s = (Array.isArray(r) ? r : []).find((x) => x.id === rt.sid);
    if (!s) { stale('Услуга не найдена.', [btn('К услугам', 'asv')]); break; }
    text = `${s.title}\nДлительность: ${s.min} мин\nЦена: ${rub(s.price) || 'не указана'}\nСтатус: ${s.active ? 'показана клиентам' : 'скрыта'}`;
    kb = [[btn('Изменить', `ase:${s.id}`)], [btn(s.active ? 'Скрыть' : 'Вернуть', `asa:${s.id}:${s.active ? 0 : 1}`)], [btn('Назад', 'asv')]];
    break;
  }
  case 'ask_edit':
    text = 'Напишите одной строкой: название; минуты; цена в рублях. Например: Стрижка; 60; 1500';
    kb = [[btn('Отмена', 'asv')]];
    state = { step: 'aedit', data: rt.st };
    break;
  case 'ask_new':
    text = 'Новая услуга. Напишите одной строкой: название; минуты; цена в рублях. Например: Маникюр; 90; 2000';
    kb = [[btn('Отмена', 'asv')]];
    state = { step: 'anew', data: {} };
    break;
  case 'aedit_again':
    text = 'Не понял. Формат: название; минуты; цена. Например: Стрижка; 60; 1500';
    kb = [[btn('Отмена', 'asv')]];
    break;
  case 'aupd':
    text = r === true ? 'Услуга сохранена.' : 'Не удалось сохранить услугу.';
    kb = [[btn('К услугам', 'asv')]];
    state = 'clear';
    break;
  case 'aadd':
    text = r ? 'Услуга добавлена. Чтобы ее могли выбрать, привяжите мастера к услуге (пока через администратора базы).' : 'Не удалось добавить услугу.';
    kb = [[btn('К услугам', 'asv')]];
    state = 'clear';
    break;
  case 'aact':
    text = r === true ? (rt.on ? 'Услуга возвращена клиентам.' : 'Услуга скрыта от клиентов.') : 'Не удалось изменить статус услуги.';
    kb = [[btn('К услугам', 'asv')]];
    break;
  default: menuScreen();
}

const body = { text };
if (kb.length) body.attachments = [{ type: 'inline_keyboard', payload: { buttons: kb } }];
const actions = [];
if (rt.handler !== 'dup') {
  if (ev.kind === 'callback') {
    if (SCREEN_MODE === 'edit' && ev.mid) {
      actions.push({ op: 'edit', method: 'PUT', url: `${API}/messages?message_id=${encodeURIComponent(ev.mid)}`, body });
      actions.push({ op: 'answer', method: 'POST', url: `${API}/answers?callback_id=${encodeURIComponent(ev.callback_id)}`, body: notification ? { notification } : {} });
    } else {
      actions.push({ op: 'answer', method: 'POST', url: `${API}/answers?callback_id=${encodeURIComponent(ev.callback_id)}`, body: notification ? { message: body, notification } : { message: body } });
    }
  } else {
    actions.push({ op: 'send', method: 'POST', url: `${API}/messages?user_id=${ev.user_id}`, body });
  }
  for (const n of notes) actions.push({ op: 'notify', method: 'POST', url: `${API}/messages?user_id=${n.user_id}`, body: { text: n.text } });
}
let st = { set: false, step: '', data: {} };
if (state === 'clear') st = { set: true, step: '', data: {} };
else if (state !== 'keep') st = { set: true, step: state.step, data: JSON.parse(JSON.stringify(state.data || {})) };
// a button that opens a text step must also reset stale text steps; a plain screen change keeps the current step
return [{ json: { user_id: ev.user_id, dry: ev.dry === true, handler: rt.handler, actions,
  state_set: st.set, state_step: st.step, state_data: JSON.stringify(st.data) } }];

const r = $('Render').first().json;
if (r.dry) return [];
return (r.actions || []).map((a) => ({ json: a }));
